    m = LatencyMonitor(100)
    for t, v in [(1, 1), (2, 2), (3, 2)]:
        m.record("x", t, v)
    assert m.average("x", 3) == 1.67

def test_same_timestamp_many_samples():
    m = LatencyMonitor(1)
    for v in range(10):
        m.record("x", 7, v)
    assert m.average("x", 7) == 4.5
    assert m.average("x", 8) is None

def test_large_stream_is_fast():
    m = LatencyMonitor(1000)
    total = 0
    for t in range(100_000):
        m.record("hot", t, t % 100)
        if t % 10 == 0:
            total += m.average("hot", t)
    window = [t % 100 for t in range(99_000, 100_000)]
    assert m.average("hot", 99_999) == round(sum(window) / len(window), 2)

