from collections import defaultdict, deque


class LatencyMonitor:
    def __init__(self, window_seconds: int):
        self.window = window_seconds
        self.samples: dict[str, deque[tuple[int, int]]] = defaultdict(deque)
        self.sums: dict[str, int] = defaultdict(int)

    def _evict(self, endpoint: str, now: int) -> None:
        q = self.samples[endpoint]
        while q and q[0][0] <= now - self.window:
            self.sums[endpoint] -= q.popleft()[1]

    def record(self, endpoint: str, timestamp: int, latency_ms: int) -> None:
        self.samples[endpoint].append((timestamp, latency_ms))
        self.sums[endpoint] += latency_ms
        self._evict(endpoint, timestamp)

    def average(self, endpoint: str, now: int) -> float | None:
        if endpoint not in self.samples:
            return None
        self._evict(endpoint, now)
        q = self.samples[endpoint]
        return round(self.sums[endpoint] / len(q), 2) if q else None
